from collections import defaultdict
import heapq


def solve(value):
    data = value.get('data', [])
    options = value.get('options', {})

    eligible_tasks = []
    task_map = {}

    for task in data:
        task_id = task.get('id')
        status = task.get('status')
        priority = task.get('priority', 0)
        dependencies = task.get('dependencies', [])
        task_map[task_id] = {
            'status': status,
            'priority': priority,
            'dependencies': dependencies
        }

    for task_id, task in task_map.items():
        if task['status'] in ['queued', 'retry']:
            continue

        if task['status'] in ['running', 'tested', 'failed', 'cancelled']:
            continue

        dependencies = task['dependencies']
        all_deps_tested = True
        for dep_id in dependencies:
            if dep_id not in task_map:
                all_deps_tested = False
                break
            if task_map[dep_id]['status'] != 'tested':
                all_deps_tested = False
                break

        if all_deps_tested:
            eligible_tasks.append((task['priority'], task_id))

    eligible_tasks.sort(key=lambda x: (-x[0], x[1]))
    order = [task_id for priority, task_id in eligible_tasks]

    return {'order': order}

